function Bind-BalancePin($Record,[switch]$Include){
    $path=if($Record.path){$Record.path}else{$Record.file};$actual=Get-HoverIdentity $path
    if($Record.sha256 -ne $actual.sha256 -or ($Record.bytes -and $Record.bytes -ne $actual.bytes)){throw "Evidence identity changed: $path"}
    $bound.Add($actual);if($Include){$null=Pin-ModelInput $path};return $actual
}
function Assert-BalancePass($Report,[string]$Label){if($Report.passed -ne $true -or @($Report.errors|Where-Object {$_}).Count -or $Report.failure){throw "Required actual acceptance failed: $Label"}}
function Assert-BalanceArenaAlignment($Geometry,[switch]$RequireTowers){
    if(!$Geometry -or $Geometry.passed -ne $true -or $Geometry.widthTiles -ne 30 -or $Geometry.heightTiles -ne 44 -or $Geometry.lanePathsPassed -ne $true -or $Geometry.lanePaverCount -ne 36 -or $Geometry.expectedLanePaverCount -ne 36 -or @($Geometry.lanePavers).Count -ne 36 -or @($Geometry.lanePaths).Count -ne 4){throw 'Actual rendered arena/stone-path alignment is incomplete.'}
    if(@($Geometry.lanePaths|ForEach-Object{"$($_.team),$($_.lane)"}|Sort-Object -Unique).Count -ne 4 -or @($Geometry.lanePavers|ForEach-Object{"$($_.x),$($_.z)"}|Sort-Object -Unique).Count -ne 36){throw 'Actual stone paths contain duplicate lanes or pavers.'}
    foreach($path in $Geometry.lanePaths){foreach($field in @('team','lane','centerX','minimumX','maximumX','pavers','rows')){if($null -eq $path.$field){throw 'An actual stone-path field is missing.'}};$rows=if($path.team -eq 'player'){5}else{4};$center=$path.lane*7.2;if($path.team -notin @('player','enemy') -or $path.lane -notin @(-1,1) -or $path.alignmentPassed -ne $true -or $path.rows -ne $rows -or $path.pavers -ne 2*$rows -or [Math]::Abs($path.centerX-$center) -gt .001 -or [Math]::Abs($path.minimumX-($center-.5)) -gt .001 -or [Math]::Abs($path.maximumX-($center+.5)) -gt .001){throw 'An actual stone path is not centered on its bridge.'};$actual=@($Geometry.lanePavers|Where-Object {($_.z -gt 0) -eq ($path.team -eq 'player') -and [Math]::Abs($_.x-$center) -le .501});if($actual.Count -ne 2*$rows -or @($actual.z|Sort-Object -Unique).Count -ne $rows){throw 'Reported stone path counts differ from actual HISM pavers.'};foreach($paver in $actual){if($null -eq $paver.x -or $null -eq $paver.z -or [Math]::Abs([Math]::Abs($paver.x-$center)-.5) -gt .001){throw 'Actual stone-path columns are not equally spaced around the bridge center.'}}}
    if($RequireTowers){
        if($Geometry.towerSnapshotAvailable -ne $true -or $Geometry.towerAlignmentPassed -ne $true -or $Geometry.guardsAligned -ne 4 -or $Geometry.coresCentered -ne 2 -or @($Geometry.towers).Count -ne 6 -or @($Geometry.towers.id|Sort-Object -Unique).Count -ne 6 -or @($Geometry.towers|ForEach-Object{"$($_.team),$($_.lane)"}|Sort-Object -Unique).Count -ne 6){throw 'Battle capture lacks six actual aligned tower bodies/visuals.'}
        foreach($tower in $Geometry.towers){foreach($field in @('id','team','kind','lane','x','z','dead','visualAvailable')){if($null -eq $tower.$field){throw 'An actual tower body/visual field is missing.'}};if($tower.dead -isnot [bool] -or $tower.visualAvailable -isnot [bool]){throw 'Actual tower lifetime/visual availability is not captured.'};$core=$tower.kind -eq 'core';$sign=if($tower.team -eq 'player'){1.}else{-1.};$x=if($core){0.}else{$tower.lane*7.2};$z=$sign*$(if($core){17.3}else{13.4});if($tower.team -notin @('player','enemy') -or $tower.kind -notin @('core','guard') -or ($core -and $tower.lane -ne 0) -or (!$core -and $tower.lane -notin @(-1,1)) -or $tower.alignmentPassed -ne $true -or (!$tower.dead -and !$tower.visualAvailable) -or [Math]::Abs($tower.x-$x) -gt .001 -or [Math]::Abs($tower.z-$z) -gt .001){throw 'An actual tower body differs from the aligned geometry.'};if($tower.visualAvailable -and ($null -eq $tower.visualX -or $null -eq $tower.visualZ -or [Math]::Abs($tower.visualX-$x) -gt .001 -or [Math]::Abs($tower.visualZ-$z) -gt .001)){throw 'An available actual tower visual differs from the aligned geometry.'}}
        if(@($Geometry.towers|Where-Object kind -eq 'core').Count -ne 2 -or @($Geometry.towers|Where-Object kind -eq 'guard').Count -ne 4){throw 'Actual tower kinds differ from the retained six-tower arena.'}
    }
}
function Assert-BalanceReplayWorkloads([string]$Root,$NativeContext){
    $probe=Read-ModelInput ($Root+'/verification.json');Assert-BalancePass $probe 'final source-pinned replay workload';$before=Read-ModelInput ($Root+'/before-source-pins.json')
    if($probe.schema -ne 'rift.balance-patch.replay-workload-probe.v1' -or $probe.sourcePinsUnchanged -ne $true -or @($probe.sourcePins).Count -ne 9 -or @($before).Count -ne 9 -or @($probe.sourcePins.path|Sort-Object -Unique).Count -ne 9){throw 'Replay workload source context is incomplete.'}
    foreach($pin in $probe.sourcePins){$actual=Bind-BalancePin $pin -Include;$pre=@($before|Where-Object path -eq $pin.path);if($pre.Count -ne 1 -or $pre[0].sha256 -ne $actual.sha256 -or $pre[0].bytes -ne $actual.bytes){throw 'Replay source context differs from its actual pre-run pins.'};if($actual.path.StartsWith('Unreal/')){$nativePin=@($NativeContext.sourceHashes|Where-Object path -eq $actual.path);if($nativePin.Count -ne 1 -or $nativePin[0].sha256 -ne $actual.sha256){throw 'Replay source differs from the accepted native suite.'}}}
    foreach($name in @('RiftSimulation.cpp','RiftCombat.cpp','RiftPathfinding.cpp','RiftDeckAnalysis.cpp','RiftAI.cpp','RiftSimulation.h','RiftIntegrationTests.cpp','ReplaySeedProbe.cpp','Run-Probe.ps1')){if(@($probe.sourcePins|Where-Object {[IO.Path]::GetFileName($_.path) -eq $name}).Count -ne 1){throw 'Replay context lacks an authoritative core/fixture/probe source.'}}
    $null=Bind-BalancePin $probe.log -Include;$null=Bind-BalancePin $probe.executable;foreach($file in @('compile.cmd','compile.log')){$null=Pin-ModelInput ($Root+'/'+$file)}
    $raw=@([IO.File]::ReadLines((Resolve-ModelInput $probe.log.path))|ForEach-Object {$_|ConvertFrom-Json -Depth 100});$tracePins=[Collections.Generic.List[object]]::new()
    foreach($pin in $probe.traces){$actual=Bind-BalancePin $pin;if(!$actual.path.StartsWith($Root.TrimEnd('/')+'/') -or !$actual.path.EndsWith('.jsonl')){throw 'Replay trace identity escapes its isolated probe directory.'};$tracePins.Add($actual)}
    if(@($tracePins.path|Sort-Object -Unique).Count -ne $tracePins.Count){throw 'Replay probe repeats trace paths.'};$witnesses=[Collections.Generic.List[object]]::new();$includedHashes=[Collections.Generic.HashSet[string]]::new()
    foreach($congestion in @($false,$true)){
        $kind=if($congestion){'congested_repeat'}else{'repeat'};$prefix=if($congestion){'congested'}else{'ordinary'};$seed=if($congestion){32}else{25};$minimumPeak=if($congestion){40}else{20};$repeats=if($congestion){@($probe.congestedRepeats)}else{@($probe.repeats)};$rawRepeats=@($raw|Where-Object kind -eq $kind)
        if($repeats.Count -ne 3 -or $rawRepeats.Count -ne 3){throw 'Replay workload requires three actual ordinary and three congestion repeats.'}
        $pins=@();for($index=0;$index -lt 3;$index++){$summary=$repeats[$index];if($summary.kind -ne $kind -or $summary.seed -ne $seed -or $summary.congestion -ne $congestion -or $summary.valid -ne $true -or $summary.finished -ne $true -or $summary.zeroCrownOvertime -ne $true -or $summary.elapsed -le 180 -or $summary.elapsed -gt 360 -or $summary.spent0 -le 100 -or $summary.spent1 -le 100 -or $summary.peak -lt $minimumPeak -or $summary.winner -notin @(0,1) -or $summary.expectedReplaySamples -ne $summary.loops+2 -or ($summary|ConvertTo-Json -Depth 20 -Compress) -ne ($rawRepeats[$index]|ConvertTo-Json -Depth 20 -Compress)){throw 'Replay repeat does not retain the real terminal/overtime/paid/population workload.'};foreach($field in @('seed','elapsed','peak','spent0','spent1','winner','loops','events','expectedReplaySamples')){if($summary.$field -ne $repeats[0].$field){throw 'Replay repeat summaries are not deterministic.'}};$pin=@($tracePins|Where-Object path -eq ($Root+'/'+$prefix+'-repeat'+$index+'.jsonl'));if($pin.Count -ne 1){throw 'Accepted replay repeat lacks an actual bound trace.'};$pins+=$pin[0]}
        if(@($pins.sha256|Sort-Object -Unique).Count -ne 1 -or @($pins.bytes|Sort-Object -Unique).Count -ne 1){throw 'Actual replay repeats are not byte-identical.'};$summary=$repeats[0];$count=0;$events=0;$peak=0;$zeroOvertime=$false;$previousElapsed=-1.;$last=$null
        foreach($line in [IO.File]::ReadLines((Resolve-ModelInput $pins[0].path))){$row=$line|ConvertFrom-Json -Depth 100;if($row.elapsed -le $previousElapsed -or $row.phase -notin @(0,1,2,3)){throw 'Actual replay trace has an invalid timeline/phase.'};if($count -eq 0 -and ($row.elapsed -ne 0 -or $row.rng -ne $seed -or @($row.entities).Count -ne 6)){throw 'Actual replay trace lacks its seeded six-tower initial state.'};$previousElapsed=$row.elapsed;++$count;$events+=@($row.events).Count;$peak=[Math]::Max($peak,@($row.entities).Count);$zeroOvertime=$zeroOvertime -or ($row.phase -eq 1 -and $row.crowns[0] -eq 0 -and $row.crowns[1] -eq 0);$last=$row}
        if($count -ne $summary.loops+1 -or $summary.expectedReplaySamples -ne $count+1 -or $events -ne $summary.events -or $peak -ne $summary.peak -or !$zeroOvertime -or $last.phase -ne 3 -or $last.winner -ne $summary.winner -or [Math]::Abs($last.elapsed-$summary.elapsed) -gt 1.e-8 -or $last.spent[0] -ne $summary.spent0 -or $last.spent[1] -ne $summary.spent1){throw 'Independent raw replay timeline metrics differ from accepted repeat summaries.'}
        if(!$includedHashes.Add($pins[0].sha256)){throw 'Ordinary and congestion witnesses unexpectedly share one trace.'};$null=Pin-ModelInput $pins[0].path;$witnesses.Add([ordered]@{seed=$seed;congestion=$congestion;repeatTraces=$pins;includedWitness=$pins[0];actualTimelineRows=$count;expectedReplaySamples=$count+1;actualEvents=$events;peak=$peak;elapsed=$last.elapsed;spent=$last.spent})
    }
    $coordinate=Read-ModelInput ($Root+'/coordinate-repeat-audit.json');Assert-BalancePass $coordinate 'independent replay coordinate-repeat audit'
    if($coordinate.schema -ne 'rift.replay.coordinate-repeat-audit.v1' -or $coordinate.version -ne $Version -or @($coordinate.sourcePins).Count -ne 9 -or @($coordinate.modes).Count -ne 2 -or @($coordinate.checks.PSObject.Properties|Where-Object Value -ne $true).Count){throw 'Independent replay coordinate audit is incomplete.'}
    foreach($pin in @($coordinate.auditTool,$coordinate.verification,$coordinate.nativeFixture)+@($coordinate.sourcePins)){$null=Bind-BalancePin $pin -Include};$null=Bind-BalancePin $coordinate.historicalSearch -Include
    foreach($witness in $witnesses){$modeName=if($witness.congestion){'congested'}else{'ordinary'};$mode=@($coordinate.modes|Where-Object mode -eq $modeName);if($mode.Count -ne 1 -or $mode[0].passed -ne $true -or @($mode[0].checks.PSObject.Properties|Where-Object Value -ne $true).Count -or @($mode[0].tracePins).Count -ne 3 -or $mode[0].uniqueCoordinateWitness.sha256 -ne $witness.includedWitness.sha256 -or $mode[0].independentRawSummary.seed -ne $witness.seed -or $mode[0].independentRawSummary.peak -ne $witness.peak -or $mode[0].independentRawSummary.events -ne $witness.actualEvents -or $mode[0].independentRawSummary.expectedReplaySamples -ne $witness.expectedReplaySamples){throw 'Independent replay coordinate audit differs from the current actual witnesses.'};foreach($pin in $mode[0].tracePins){$actual=Bind-BalancePin $pin;if($actual.path -notin $witness.repeatTraces.path){throw 'Coordinate repeat audit references a different actual trace.'}}}
    return [ordered]@{proof=$Root+'/verification.json';coordinateAudit=$Root+'/coordinate-repeat-audit.json';historicalSearch=$coordinate.historicalSearch;sourcePins=$probe.sourcePins;actualRepeatCount=6;uniqueIncludedWitnesses=2;witnesses=$witnesses.ToArray();scope='Portable authoritative full-match traces; the accepted native suite independently exercises replay recording, archive import and seeking. Historical search evidence remains separate from the final accepted repeats.'}
}
