foreach($pin in $portable.sourcePins){$null=Bind-BalancePin $pin -Include};$null=Bind-BalancePin $portable.log -Include;$null=Bind-BalancePin $portable.preRunSourcePinRecord -Include;$portableExe=Bind-BalancePin $portable.executable
